import re
import operator
from taf.ul.parser.pcap.exceptions import FilterOperatorError


OPT_FUNC = {
    ">": operator.gt,
    ">=": operator.ge,
    "==": operator.eq,
    "=<": operator.le,
    "<": operator.lt,
    "!=": operator.ne
}


class Filter(object):
    _SEPARATOR_REG = r"([<>!=]+)"

    def __init__(self, logic_expression, field_expressions):
        self._logic_expression = logic_expression
        self._field_expressions = field_expressions

    def is_packet_matched(self, packet):
        each_expression_result = dict([(flag, self._is_expression_matched(packet, field_expression))
                                       for flag, field_expression in self._field_expressions.items()])
        final_result = self._logic_expression.format(**each_expression_result)
        return eval(final_result)

    def _is_expression_matched(self, packet, expression):
        if re.search(self._SEPARATOR_REG, expression):
            return self._check_comparison_for_field(packet, expression)
        elif ' ' not in expression:
            filed_name = expression
            return self._check_presence_of_field(packet, filed_name)
        else:
            raise FilterOperatorError(expression)

    def _check_comparison_for_field(self, packet, expression):
        left_value, operator_symbol, right_value = re.split(self._SEPARATOR_REG, expression)
        left_value, right_value = left_value.strip(), right_value.strip()
        is_left_field = self._check_presence_of_field(packet, left_value)
        is_right_field = self._check_presence_of_field(packet, right_value)
        if is_left_field and is_right_field:
            return self._is_comparison_between_fields_matched(packet, left_value, right_value, operator_symbol)
        elif is_left_field:
            return self._is_field_values_match_expected(packet, left_value, right_value, operator_symbol)
        elif is_right_field:
            return self._is_field_values_match_expected(packet, right_value, left_value, operator_symbol)
        else:
            return False

    @staticmethod
    def _check_presence_of_field(packet, field_name):
        field_regex = "^{}$".format(field_name)
        return True if field_regex in packet else False

    @staticmethod
    def _get_field_values_from_packet(packet, field_name, attrib_name="value"):
        field_regex = "{}$".format(field_name)
        return [getattr(field, attrib_name) for field in packet.findall(field_regex)]

    def _is_field_values_match_expected(self, packet, field_name, expected_value, operator_symbol):
        field_values = self._get_field_values_from_packet(packet, field_name, "show")
        if expected_value.startswith("0x"):
            expected_value = int(expected_value, base=16)
            field_values = [int(field_value, base=16) for field_value in field_values]

        for field_value in field_values:
            if self._compare_with_operator(expected_value, operator_symbol, field_value):
                return True
        return False

    def _is_comparison_between_fields_matched(self, packet, left_value, right_value, operator_symbol):
        left_field_values = self._get_field_values_from_packet(packet, left_value)
        right_field_values = self._get_field_values_from_packet(packet, right_value)
        operator_symbol = operator_symbol.strip()
        if operator_symbol in [">", ">="]:
            left_max = max(left_field_values)
            right_min = min(right_field_values)
            return self._compare_with_operator(left_max, operator_symbol, right_min)

        elif operator_symbol in ["<", "<="]:
            left_min = min(left_field_values)
            right_max = max(right_field_values)
            return self._compare_with_operator(left_min, operator_symbol, right_max)

        elif operator_symbol == "!=":
            return len(set(left_field_values) & set(right_field_values)) <= 0

        elif operator_symbol == "==":
            return len(set(left_field_values) & set(right_field_values)) <= 0

        else:
            raise FilterOperatorError("{}{}{}".format(left_value, operator_symbol, right_value))

    @staticmethod
    def _compare_with_operator(left_value, symbol, right_value):
        return OPT_FUNC[symbol](left_value, right_value)
